        "arguments": {
          "proposals": [
            {
              "itemId": "ARCH-01",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Festlegung auf eine reine Mobile-App ist eine Architekturentscheidung und schränkt betroffene Umsetzungen auf mobile Kanäle ein.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-025",
                "PBI-030"
              ]
            },
            {
              "itemId": "ARCH-02",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Dies rahmt den fachlichen Zweck der Lösung und begrenzt betroffene Facharbeit auf das Ziel des besseren Verstehens statt anderer Kommunikationsziele.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-027",
                "PBI-029"
              ]
            },
            {
              "itemId": "ARCH-03",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der Kernansatz beschreibt die tragende Lösungsentscheidung und schränkt fachlich die Ausgestaltung der Profil- und Kommunikationsfunktionen auf nachschlagbares Wissensangebot ein.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-012",
                "PBI-013",
                "PBI-018"
              ]
            },
            {
              "itemId": "ARCH-04",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der Ausschluss eines bidirektionalen Individual-Übersetzers ist eine klare Negativentscheidung und begrenzt die fachliche Lösungsausprägung.",
              "targetPbiIds": [
                "PBI-001",
                "PBI-018",
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-05",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Bestandssituation klassischer Akten schränkt Entscheidungen zur Datenübernahme und Dokumentationsintegration fachlich ein.",
              "targetPbiIds": [
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-06",
              "roles": [
                "constraint"
              ],
              "rationale": "Die angenommene schlechte Nutzbarkeit vorhandener Akten begründet fachlichen Druck auf schnellen, kompakten Zugriff und beeinflusst die Betrachtung von Dokumentationsübernahme.",
              "targetPbiIds": [
                "PBI-009",
                "PBI-027"
              ]
            },
            {
              "itemId": "ARCH-07",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Login ohne Selbstregistrierung ist eine Sicherheits- und Betriebsentscheidung und schränkt die Account-Umsetzung entsprechend ein.",
              "targetPbiIds": [
                "PBI-002",
                "PBI-005"
              ]
            },
            {
              "itemId": "ARCH-08",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Mindestrollen Admin und User samt Löschverbot für User sind eine Architekturentscheidung und schränken Account- und Rechtemodell direkt ein.",
              "targetPbiIds": [
                "PBI-002",
                "PBI-003"
              ]
            },
            {
              "itemId": "ARCH-09",
              "roles": [
                "constraint"
              ],
              "rationale": "Der Zugriff für Angehörige mit abweichenden Rechten schränkt das auszuarbeitende Rechtemodell fachlich ein.",
              "targetPbiIds": [
                "PBI-003"
              ]
            },
            {
              "itemId": "ARCH-10",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Der Bewohner-Account mit stark begrenztem Eigenzugriff ist eine Rollenentscheidung und schränkt Rechtemodell sowie Sicht auf About Me ein.",
              "targetPbiIds": [
                "PBI-003",
                "PBI-013",
                "PBI-014"
              ]
            },
            {
              "itemId": "ARCH-11",
              "roles": [
                "constraint",
                "work"
              ],
              "rationale": "Die Beschränkung auf die eigene Einrichtung ist eine harte Rahmenbedingung für das Rechtemodell; zugleich entsteht technische Arbeit für Mandanten- oder Einrichtungssicht.",
              "targetPbiIds": [
                "PBI-003"
              ]
            },
            {
              "itemId": "ARCH-12",
              "roles": [
                "design"
              ],
              "rationale": "Der Fakt sagt aktuell vor allem aus, dass die konkrete Rechteverwaltung noch offen ist; das ist dokumentierbares Entscheidungswissen, aber noch keine direkte technische Arbeit.",
              "targetPbiIds": null
            },
            {
              "itemId": "ARCH-13",
              "roles": [
                "design"
              ],
              "rationale": "Ein separater Admin-Bildschirm ist derzeit eine zu prüfende Lösungsoption und damit vor allem dokumentierbares Architekturwissen.",
              "targetPbiIds": null
            },
            {
              "itemId": "ARCH-14",
              "roles": [
                "constraint"
              ],
              "rationale": "Datenschutz und Einwilligungen für Bilder begrenzen direkt die Umsetzung bildbezogener Funktionen im About-Me-Bereich.",
              "targetPbiIds": [
                "PBI-014",
                "PBI-015"
              ]
            },
            {
              "itemId": "ARCH-15",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Profilübersicht nach dem Login ist eine strukturelle UI-Entscheidung und begrenzt Login- und Navigationsfluss.",
              "targetPbiIds": [
                "PBI-005",
                "PBI-009"
              ]
            },
            {
              "itemId": "ARCH-16",
              "roles": [
                "constraint"
              ],
              "rationale": "Die Suchleiste ist eine fachliche Vorgabe für die Profilübersicht und schränkt deren Umsetzung direkt ein.",
              "targetPbiIds": [
                "PBI-009"
              ]
            },
            {
              "itemId": "ARCH-17",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Darstellung von Profilen mit Bild, Name und Kurzbeschreibung ist eine UI-Entscheidung und begrenzt die Ausgestaltung der Profilkarten.",
              "targetPbiIds": [
                "PBI-009",
                "PBI-011"
              ]
            },
            {
              "itemId": "ARCH-18",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die Detailansicht mit großem Bild und Bereichsbuttons ist eine tragende Strukturentscheidung und schränkt die Profil-Detailseite ein.",
              "targetPbiIds": [
                "PBI-012"
              ]
            },
            {
              "itemId": "ARCH-19",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die About-Me-Seite als eigener Bereich mit Kurzinfo und Bildern ist eine Fach- und Strukturentscheidung und begrenzt die entsprechende Umsetzung.",
              "targetPbiIds": [
                "PBI-013",
                "PBI-014"
              ]
            },
            {
              "itemId": "ARCH-20",
              "roles": [
                "design",
                "constraint"
              ],
              "rationale": "Die dynamische Foto-Timeline mit Upload und Sortierung ist eine konkrete Lösungsentscheidung und schränkt die About-Me-Umsetzung ein.",
              "targetPbiIds": [
                "PBI-014"
              ]
            },
            {
              "itemId": "ARCH-21",
              "roles": [
                "design",
