        "id": "call_N6TciWSojdzSj2PqASIFWta3",
        "response": [
          {
            "itemId": "ARCH-01",
            "text": "Die Lösung bleibt eine digitale App zur Förderung der Kommunikation und wird als reine Mobile-App ohne Web-Client ausgeführt.",
            "sourceClaimIds": [
              "no-go-global-statt-pro-bewohner"
            ]
          },
          {
            "itemId": "ARCH-02",
            "text": "Die Unterstützung soll vorrangig darauf ausgerichtet sein, dass Betreuer oder andere Personen Bewohner besser verstehen können.",
            "sourceClaimIds": [
              "canon-priorisierung-bewohner-besser-verstehen"
            ]
          },
          {
            "itemId": "ARCH-03",
            "text": "Als Kernansatz soll die App Wissen über Profil und Kommunikationsweise einer Person bereitstellen, damit Nutzer bei Verständnisschwierigkeiten nachsehen können; die konkrete Ausprägung dieses Ansatzes ist noch weiter auszuarbeiten.",
            "sourceClaimIds": [
              "canon-app-profilwissen-kommunikationshilfe"
            ]
          },
          {
            "itemId": "ARCH-04",
            "text": "Ein System, das individuell zwischen Bewohner und Betreuer in beide Richtungen übersetzt, ist als Lösungsansatz ausgeschlossen.",
            "sourceClaimIds": [
              "canon-ausschluss-individual-uebersetzer"
            ]
          },
          {
            "itemId": "ARCH-05",
            "text": "Bestehende klassische Akten und Dokumentationen zu Bewohnern sind als Bestandssituation zu berücksichtigen.",
            "sourceClaimIds": [
              "canon-ist-situation-dokumentation"
            ]
          },
          {
            "itemId": "ARCH-06",
            "text": "Es muss berücksichtigt werden, dass vorhandene Akten im Arbeitsalltag schwer nutzbar sein können, weil sie umfangreich sind und gesuchte Informationen nicht schnell gefunden werden; dies ist jedoch nur als persönliche Einschätzung belegt.",
            "sourceClaimIds": [
              "canon-risiko-akten-schwer-nutzbar"
            ]
          },
          {
            "itemId": "ARCH-07",
            "text": "Die App darf keine Selbstregistrierung erlauben; Zugang erfolgt nur per Login mit intern vergebenen Accounts.",
            "sourceClaimIds": [
              "canon-login-ohne-selbstregistrierung"
            ]
          },
          {
            "itemId": "ARCH-08",
            "text": "Es muss mindestens die Rollen Admin und User geben; Admins verwalten Accounts und Rechte, User können Inhalte hinzufügen, aber nichts löschen.",
            "sourceClaimIds": [
              "canon-rollen-admin-user"
            ]
          },
          {
            "itemId": "ARCH-09",
            "text": "Neben Mitarbeitern sollen auch Angehörige Zugriff auf die App erhalten und Inhalte beziehungsweise Wissen beitragen können; unterschiedliche Rechte sind dabei vorgesehen, aber noch nicht konkret ausformuliert.",
            "sourceClaimIds": [
              "canon-angehoerige-zugriff-und-beitrag"
            ]
          },
          {
            "itemId": "ARCH-10",
            "text": "Zusätzlich soll es einen Bewohner-Account geben, der nur das eigene Profil sehen darf und nur eingeschränkte Funktionen nutzen kann, insbesondere Zugriff auf About Me und gegebenenfalls das Hinzufügen eigener Bilder.",
            "sourceClaimIds": [
              "canon-bewohner-account-mit-beschraenkung"
            ]
          },
          {
            "itemId": "ARCH-11",
            "text": "Mitarbeiter dürfen nicht einrichtungsübergreifend auf alle Profile zugreifen, sondern nur auf Profile der Einrichtung, in der sie tätig sind; die technische Umsetzung dieser Beschränkung ist noch zu erarbeiten.",
            "sourceClaimIds": [
              "canon-zugriff-nach-einrichtung-beschraenkt"
            ]
          },
          {
            "itemId": "ARCH-12",
            "text": "Die konkrete Ausgestaltung der Rechteverwaltung ist noch nicht festgelegt und muss später entschieden werden.",
            "sourceClaimIds": [
              "canon-rechteverwaltung-noch-offen"
            ]
          },
          {
            "itemId": "ARCH-13",
            "text": "Für die Rechte- und Accountverwaltung soll ein separater Admin-Bildschirm erwogen werden, auf dem nur Admins Accounts anlegen und Rollen vergeben können.",
            "sourceClaimIds": [
              "canon-admin-screen-pruefen"
            ]
          },
          {
            "itemId": "ARCH-14",
            "text": "Vor Nutzung von Bildern in der App müssen Datenschutzfragen und Einwilligungen der Angehörigen beziehungsweise Berechtigten geklärt werden, auch für Testbilder.",
            "sourceClaimIds": [
              "canon-datenschutz-bilder-einwilligungen"
            ]
          },
          {
            "itemId": "ARCH-15",
            "text": "Nach dem Login soll eine Profilübersicht mit anklickbarer Liste der sichtbaren Bewohnerprofile angezeigt werden.",
            "sourceClaimIds": [
              "canon-profiluebersicht-nach-login"
            ]
          },
          {
            "itemId": "ARCH-16",
            "text": "Auf der Profilübersicht soll eine Suchleiste vorhanden sein, um Profile schnell nach Namen zu finden.",
            "sourceClaimIds": [
              "canon-suche-profile"
            ]
          },
          {
            "itemId": "ARCH-17",
            "text": "Profile sollen in der Übersicht mit Vorschaubild, Name und Kurzbeschreibung dargestellt werden; ob dies als Liste oder Kacheln erfolgt, ist noch offen.",
            "sourceClaimIds": [
              "canon-profiluebersicht-darstellung"
            ]
          },
          {
            "itemId": "ARCH-18",
            "text": "Die Detailansicht eines Profils soll das Profilbild größer zeigen und die Hauptbereiche der App als interaktive Buttons anbieten; der genaue Zuschnitt dieser Hauptbereiche ist noch nicht stabil.",
            "sourceClaimIds": [
              "canon-profil-detail-mit-hauptbereichen"
            ]
          },
          {
            "itemId": "ARCH-19",
            "text": "Die App soll je Bewohner eine About-Me-Seite mit persönlicher Kurzinfo, Bildern und beschreibenden Informationen für den ersten Eindruck bereitstellen.",
            "sourceClaimIds": [
              "canon-about-me-seite"
            ]
          },
          {
            "itemId": "ARCH-20",
            "text": "Die About-Me-Ansicht soll eine dynamisch erweiterbare Foto-Timeline mit Beschreibungen bereitstellen, bei der neue Einträge per Plus-Button hinzugefügt werden und die neuesten oben erscheinen.",
            "sourceClaimIds": [
              "canon-about-me-fototimeline-erweiterbar"
            ]
          },
          {
            "itemId": "ARCH-21",
            "text": "Die App soll eine Kommunikationsansicht mit klarer Unterteilung in verbale und nonverbale Kommunikation bereitstellen.",
            "sourceClaimIds": [
              "canon-kommunikationsansicht-verbal-nonverbal"
            ]
          },
          {
            "itemId": "ARCH-22",
            "text": "Einträge zu Kommunikationsweisen müssen dynamisch erweiterbar sein und sollen nicht nur als Text, sondern auch mit Bildern und weiteren Darstellungsformen erfasst und angezeigt werden können.",
            "sourceClaimIds": [
              "canon-kommunikationseintraege-dynamisch-multimodal"
            ]
          },
          {
            "itemId": "ARCH-23",
            "text": "Videos von Kommunikationssituationen sollen mit Beschreibungen erfasst werden können und als Teil der Kommunikationsseiten statt als separater Screen integriert sein.",
            "sourceClaimIds": [
              "canon-videos-in-kommunikation"
            ]
          },
          {
            "itemId": "ARCH-24",
            "text": "Auf Kommunikationsseiten soll eine Suchfunktion vorhanden sein; dafür muss ein standardisiertes Beschreibungsmuster für Kommunikationseinträge definiert werden, damit Suche und spätere Filterung funktionieren.",
            "sourceClaimIds": [
              "canon-suche-kommunikation-und-beschreibungsmuster"
            ]
          },
          {
            "itemId": "ARCH-25",
            "text": "Die App soll eine No-Go-Seite mit dynamisch erweiterbarer Liste bereitstellen, auf der kritische Dinge festgehalten werden, die in Gegenwart des Bewohners vermieden werden müssen.",
            "sourceClaimIds": [
              "canon-no-go-seite"
            ]
          },
          {
            "itemId": "ARCH-26",
            "text": "Eine Kalenderfunktion soll erwogen werden; zusätzlich ist zu prüfen, ob auch Medikamentengaben integriert werden sollen, wobei die Vertraulichkeit dieser Daten besonders zu berücksichtigen ist.",
            "sourceClaimIds": [
              "canon-kalender-und-medikamente-pruefen"
            ]
          },
          {
            "itemId": "ARCH-27",
            "text": "Es soll erwogen werden, in der Profilübersicht das Anlegen neuer Profile per Plus-Symbol und Dialog für Bild, Name und Beschreibung zu ermöglichen.",
